import json
import os
import sys
import time
from datetime import datetime, timedelta

CONFIG_FILE = "client_config.json"
USAGE_FILE = "usage.json"

def load_config():
    with open(CONFIG_FILE, "r") as f:
        return json.load(f)

def load_usage():
    if os.path.exists(USAGE_FILE):
        with open(USAGE_FILE, "r") as f:
            return json.load(f)
    return {}

def save_usage(usage):
    with open(USAGE_FILE, "w") as f:
        json.dump(usage, f)

def validate_token(token):
    try:
        client_id, issued_at = token.split(maxsplit=1)
        issued_at = int(issued_at)
        return client_id, issued_at
    except ValueError:
        return None, None

def issue_token():
    client_id = sys.stdin.readline().strip()
    secret = sys.stdin.readline().strip()

    config = load_config()
    if client_id not in config:
        print("unknown client or secret", file=sys.stderr)
        sys.exit(1)

    if config[client_id]["secret"] != secret:
        print("unknown client or secret", file=sys.stderr)
        sys.exit(1)

    usage = load_usage()
    quota = config[client_id]["quota_per_minute"]
    current_time = time.time()

    if client_id in usage:
        recent_issues = [t for t in usage[client_id] if current_time - t <= 60]
        if len(recent_issues) >= quota:
            print("quota exceeded", file=sys.stderr)
            sys.exit(2)

    issued_at = int(time.time())
    token = f"{client_id} {issued_at}"
    expires_at = issued_at + 300

    if client_id not in usage:
        usage[client_id] = []
    usage[client_id].append(issued_at)

    save_usage(usage)
    print(token)

def verify_token():
    token = sys.stdin.readline().strip()
    client_id, issued_at = validate_token(token)
    if client_id is None:
        print("invalid token", file=sys.stderr)
        sys.exit(1)

    current_time = time.time()
    if current_time >= int(issued_at) + 300:
        print("invalid token", file=sys.stderr)
        sys.exit(1)

    expires_at = int(issued_at) + 300
    print(f"{client_id} {expires_at}")

def main():
    if len(sys.argv) != 2:
        print("Usage: tokenctl.py {issue,verify}", file=sys.stderr)
        sys.exit(1)

    command = sys.argv[1]
    if command == "issue":
        issue_token()
    elif command == "verify":
        verify_token()
    else:
        print("Invalid command", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

