import json
import sys
import time
from pathlib import Path

def read_json(file_path):
    try:
        with open(file_path, 'r') as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}

def write_json(file_path, data):
    with open(file_path, 'w') as f:
        json.dump(data, f)

def issue():
    client_id = sys.stdin.readline().strip()
    secret = sys.stdin.readline().strip()

    config = read_json('client_config.json')
    if client_id not in config or config[client_id]['secret'] != secret:
        print('unknown client or secret', file=sys.stderr)
        sys.exit(1)

    usage = read_json('usage.json')
    now = int(time.time())

    client_usage = usage.get(client_id, [])
    recent_seconds = [s for s in client_usage if now - 60 <= s <= now]

    if len(recent_seconds) >= config[client_id]['quota_per_minute']:
        print('quota exceeded', file=sys.stderr)
        sys.exit(2)

    client_usage.append(now)
    usage[client_id] = client_usage
    write_json('usage.json', usage)

    token = f"{client_id}:{now}"
    print(token)

def verify():
